import {createAdapter} from './data.js';

const root=document.getElementById('app');
const state={mode:'demo',me:null,page:'feed',viewUserId:null,activeRoom:null,watchingRoomId:null,modal:null,authMode:'login',search:'',commentOpen:{},draftTags:[],profiles:[],posts:[],comments:[],likes:[],rooms:[],messages:[],receipts:[],lastReadMarked:{},shares:[],viewPostId:null,appearanceOpen:false,accent:(()=>{try{return localStorage.getItem('unisync_accent')||'blue';}catch{return 'blue';}})(),legacyPosts:[],legacyMine:[],legacyReview:[],legacyRole:'aluno',globalAutoOpened:false,expenses:[],healthSection:'Vacinação',muralFilter:'Todas',feedFilter:'Todas',mobileMore:false,notificationsSeen:0,enterGate:true,loginRequested:false,follows:[],commentLikes:[],theme:(()=>{try{return localStorage.getItem('unisync_theme')==='dark'?'dark':'light';}catch{return 'light';}})(),shareTarget:(()=>{try{return new URLSearchParams(location.search).get('post');}catch{return null;}})()};
let api=null,toastTimer=null;document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.accent=state.accent;
const icons={feed:'✦',rooms:'◈',chats:'💬',notifications:'🔔',people:'♧',finance:'💰',health:'🌿',profile:'◉',more:'☰'};
const sections=[['feed','Feed'],['chats','Chats'],['notifications','Notificações'],['profile','Meu perfil'],['rooms','Comunidades'],['people','Pessoas'],['finance','Finanças'],['health','Saúde']];const mobileSections=[['feed','Feed'],['chats','Chats'],['notifications','Avisos'],['profile','Perfil'],['more','Mais']];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const safeImg=url=>typeof url==='string'&&(/^(https:\/\/)/i.test(url)||/^data:image\/(jpeg|png|webp);base64,/i.test(url))?url:'';
const cleanColor=c=>/^#[a-fA-F0-9]{6}$/.test(c||'')?c:'#6242d7';
const formatDate=v=>{let ms=timeValue(v)||Date.now();let d=new Date(ms);return Number.isNaN(d.valueOf())?'agora':d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});};
const formatTime=v=>{let ms=timeValue(v)||Date.now();return new Date(ms).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});};
const timeValue=v=>{if(v&&typeof v.toMillis==='function')return v.toMillis();if(typeof v?.seconds==='number')return v.seconds*1000;return Number(v)||0;};
const byRecent=(a,b)=>timeValue(b.createdAt)-timeValue(a.createdAt);
const profile=id=>state.profiles.find(p=>p.id===id)||{id,name:'Estudante',username:'estudante',university:'Universidade',tags:[]};
const me=()=>profile(state.me);
const visible=(a,...fields)=>!state.search||fields.some(s=>String(s||'').toLocaleLowerCase('pt-BR').includes(state.search.toLocaleLowerCase('pt-BR')));
const avatar=(u,cls='')=>{const p=typeof u==='string'?profile(u):u;const src=safeImg(p.avatarUrl);return src?`<img class="avatar ${cls}" alt="Foto de ${attr(p.name)}" src="${attr(src)}">`:`<div class="avatar ${cls}" aria-label="Avatar de ${attr(p.name)}">${esc((p.name||'?').charAt(0).toUpperCase())}</div>`;};
const tags=(items=[])=>items.map(t=>`<span class="pill tag" style="--tag-color:${cleanColor(t.color)}">${esc(t.name)}</span>`).join('');
const postTags=(items=[])=>items.map(t=>`<span class="pill">#${esc(t)}</span>`).join(' ');
const roomName=r=>r.kind==='direct'?(r.members.filter(x=>x!==state.me).map(x=>profile(x).name).join(', ')||'Conversa individual'):r.name;
const member=r=>Array.isArray(r.members)&&r.members.includes(state.me);
const alertToast=(msg,kind='ok')=>{let el=document.getElementById('toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';document.body.append(el);}el.textContent=(kind==='error'?'⚠️ ':'✓ ')+msg;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4400);};
const run=async(fn,success)=>{try{await fn();if(success)alertToast(success);}catch(e){console.error(e);alertToast(e.message||'Não foi possível completar a ação.','error');}};
function isModerator(){return state.legacyRole==='moderador';}
function activityEvents(){
 if(!state.me)return [];
 const mine=new Map([...state.posts.filter(p=>p.authorId===state.me),...unifiedLegacyPosts().filter(p=>p.authorId===state.me)].map(p=>[p.id,p]));
 const ownComments=new Map(state.comments.filter(c=>c.authorId===state.me).map(c=>[c.id,c]));
 const events=[];
 const append=(type,id,actorId,createdAt,postId='',postTitle='',detail='')=>{if(actorId&&actorId!==state.me)events.push({type,id,actorId,createdAt,postId,postTitle,detail});};
 state.likes.forEach(x=>{const p=mine.get(x.postId);if(p)append('like','like_'+x.id,x.userId,x.createdAt,p.id,p.title);});
 state.comments.forEach(x=>{const p=mine.get(x.postId);if(p)append('comment','comment_'+x.id,x.authorId,x.createdAt,p.id,p.title,x.text||'');});
 state.shares.forEach(x=>{const id=x.sourceType==='legacy'?'legacy_'+x.originalId:x.originalId,p=mine.get(id);if(p)append('share','share_'+x.id,x.authorId,x.createdAt,p.id,p.title,x.note||'');});
 state.follows.forEach(x=>{if(x.followingId===state.me)append('follow','follow_'+x.id,x.followerId,x.createdAt);});
 state.commentLikes.forEach(x=>{const c=ownComments.get(x.commentId);if(c){const p=getOriginal(c.postId);append('comment-like','commentlike_'+x.id,x.userId,x.createdAt,c.postId,p?.title||'Seu comentário');}});
 return events.sort(byRecent).slice(0,100);
}
const unreadCount=()=>activityEvents().filter(e=>timeValue(e.createdAt)>state.notificationsSeen).length;
function go(page){
 if(page==='more'){state.mobileMore=!state.mobileMore;render();return;}
 state.mobileMore=false;state.page=page;state.search='';
 if(page==='profile')state.viewUserId=state.me;if(page==='feed')state.viewPostId=null;
 if(page==='notifications'){state.notificationsSeen=Date.now();try{localStorage.setItem('unisync_notifications_seen_'+state.me,String(state.notificationsSeen));}catch{}}
 if(page==='chats'){if(!state.activeRoom)state.activeRoom=state.rooms.find(r=>r.id==='ufabc-global')?.id||state.rooms.find(r=>member(r))?.id||null;const currentRoom=state.rooms.find(r=>r.id===state.activeRoom);subscribeRoom(currentRoom&&member(currentRoom)?state.activeRoom:null);}
 render();
}
const navLink=([key,label])=>`<button class="nav-link ${state.page===key?'active':''}" data-action="navigate" data-id="${key}"><span class="nav-icon">${icons[key]}</span><span>${label}</span>${key==='notifications'&&unreadCount()?`<span class="nav-count">${unreadCount()}</span>`:''}</button>`;
function layout(){
 const self=me(),extra=['rooms','people','finance','health'];
 return `<div class="shell"><aside class="side"><div class="brand"><span class="legacy-logo" role="img" aria-label="Logotipo UniSync"></span></div>
 <p class="small-label">PRINCIPAL</p><nav class="nav-list" aria-label="Navegação principal">${sections.slice(0,4).map(navLink).join('')}</nav>
 <p class="small-label" style="margin-top:20px">EXPLORAR</p><nav class="nav-list" aria-label="Mais recursos">${sections.slice(4).map(navLink).join('')}</nav>
 <div class="side-card"><strong>Seu lugar é aqui ✨</strong><p>Conheça pessoas, compartilhe histórias e encontre sua comunidade.</p><button data-action="new-post">Criar publicação +</button></div></aside>
 <div class="main"><header class="topbar"><div class="brand"><span class="legacy-logo" role="img" aria-label="Logotipo UniSync"></span></div><label class="topbar-search"><span>⌕</span><input id="global-search" type="search" autocomplete="off" value="${attr(state.search)}" placeholder="Buscar pessoas, assuntos, grupos..."></label><div class="topbar-right">${state.mode==='demo'?'<span class="demo-chip">DEMO</span>':''}<button class="theme-btn" data-action="open-appearance" title="Cores e aparência">🎨</button><button class="btn sm soft" data-action="logout">Sair</button><button class="account-chip" data-action="my-profile" title="Meu perfil">${avatar(self,'tiny')}<span>${esc(self.name)}</span></button></div></header>
 <div class="layout"><main class="content" id="content" aria-live="polite">${content()}</main><aside class="rail" id="rail">${rail()}</aside></div></div></div>
 ${state.mobileMore?`<div class="more-overlay" data-action="close-more"></div><div class="more-drawer"><div class="row between"><strong>Outras áreas</strong><button class="btn sm soft" data-action="close-more">Fechar ✕</button></div><div class="more-grid">${sections.filter(([key])=>extra.includes(key)).map(([key,label])=>`<button class="more-entry" data-action="navigate" data-id="${key}"><span>${icons[key]}</span>${label}</button>`).join('')}</div></div>`:''}
 <nav class="mobile-nav" aria-label="Navegação rápida">${mobileSections.map(([key,label])=>`<button class="${key==='more'?(state.mobileMore||extra.includes(state.page)?'active':''):(state.page===key?'active':'')}" data-action="navigate" data-id="${key}"><b>${icons[key]}</b><span>${label}</span>${key==='notifications'&&unreadCount()?`<em class="mobile-count">${unreadCount()}</em>`:''}</button>`).join('')}</nav>${modal()}`;
}
function content(){if(state.page==='post')return postDetail();if(state.page==='feed')return feed();if(state.page==='notifications')return notifications();if(state.page==='rooms')return rooms();if(state.page==='chats')return chats();if(state.page==='people')return people();if(state.page==='finance')return finance();if(state.page==='health')return health();return userProfile();}
function rail(){const people=state.profiles.filter(p=>p.id!==state.me).slice(0,3);return `<section class="panel panel-pad"><div class="section-eyebrow">Descobrir</div><h3>Conecte-se com alguém</h3>${people.map(p=>`<div class="rail-row">${avatar(p,'sm')}<div class="grow"><button class="linkish" data-action="view-profile" data-id="${attr(p.id)}">${esc(p.name)}</button><div class="subline">${esc(p.university||'Universidade')}</div></div><button class="btn sm soft" data-action="start-dm" data-id="${attr(p.id)}" aria-label="Conversar com ${attr(p.name)}">💬</button></div>`).join('')}<button class="linkish" data-action="navigate" data-id="people">Ver mais pessoas →</button></section><section class="panel panel-pad"><div class="section-eyebrow">Espaço seguro</div><h3>Uma comunidade com respeito 💜</h3><p class="hint">Perfis são visíveis aos demais membros. Conversas privadas só devem ser acessíveis aos participantes. Evite divulgar dados sensíveis.</p></section>${state.mode==='demo'?`<section class="panel panel-pad"><div class="section-eyebrow">Teste interativo</div><h3>Trocar personagem</h3><p class="hint">Simule outra pessoa para testar mensagens e interações no mesmo navegador.</p><select id="demo-persona" class="field" aria-label="Usuário de demonstração">${state.profiles.map(p=>`<option value="${attr(p.id)}" ${p.id===state.me?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button class="btn sm line" data-action="reset-demo" style="margin-top:12px">Reiniciar demo</button></section>`:''}`;}
function unifiedLegacyPosts(){
 const map=new Map();
 for(const o of [...state.legacyPosts,...state.legacyMine,...state.legacyReview]){
  const id=o.legacy?o.id.slice(7):o.id;
  if(!id)continue;
  map.set(id,{id:'legacy_'+id,legacyId:id,legacy:true,authorId:o.authorId||o.autorUid||'',legacyAuthorName:o.legacyAuthorName||o.autorNome||'Estudante',legacyUni:o.legacyUni||o.autorUni||'',title:o.title||o.titulo||'Publicação',body:o.body||o.texto||'',tags:o.tags||[o.cat||'Mural'],createdAt:o.createdAt||o.data,status:o.status||'aprovado'});
 }
 return [...map.values()];
}
const postStatus=p=>p.status||'aprovado';
function getOriginal(id){if(!id)return null;return id.startsWith('legacy_')?unifiedLegacyPosts().find(p=>p.id===id)||null:state.posts.find(p=>p.id===id)||null;}
const repostCount=p=>state.shares.filter(s=>s.sourceType===(p.legacy?'legacy':'social')&&s.originalId===(p.legacy?p.legacyId:p.id)).length;
function repostCard(repost){
 const source=repost.original,who=profile(repost.authorId),originalAuthor=source.legacy?{id:source.authorId,name:source.legacyAuthorName||'Estudante',avatarUrl:'',university:source.legacyUni||''}:profile(source.authorId);
 return `<article class="panel repost-card"><div class="repost-header">${avatar(who,'sm')}<button class="linkish" data-action="view-profile" data-id="${attr(who.id)}">${esc(who.name)}</button><span class="hint">compartilhou uma publicação</span><small>${formatDate(repost.createdAt)}</small></div>
 ${repost.note?`<p class="repost-note">${esc(repost.note)}</p>`:''}
 <button class="source-preview" data-action="open-post" data-id="${attr(source.id)}"><div class="source-header">${avatar(originalAuthor,'sm')}<strong>${esc(originalAuthor.name)}</strong><span class="hint">· Publicação original</span></div><h3>${esc(source.title)}</h3><p>${esc(source.body.slice(0,380))}${source.body.length>380?'…':''}</p><span class="source-link">Abrir publicação e visitar o autor →</span></button>
 <div class="repost-footer"><span>↗ Compartilhado no UniSync</span><button class="action" data-action="share-post" data-id="${attr(source.id)}">Compartilhar também</button></div></article>`;
}
function postDetail(){
 const p=getOriginal(state.viewPostId);
 if(!p||!(postStatus(p)==='aprovado'||p.authorId===state.me||isModerator()))return `<div class="panel panel-pad"><button class="btn soft" data-action="navigate" data-id="feed">← Voltar ao Feed</button><h2 style="margin-top:18px">Publicação indisponível</h2><p>Ela pode ter sido excluída ou ainda não foi aprovada.</p></div>`;
 const totalLikes=state.likes.filter(x=>x.postId===p.id).length,totalComments=state.comments.filter(x=>x.postId===p.id).length,totalShares=repostCount(p);
 const shares=state.shares.filter(x=>x.sourceType===(p.legacy?'legacy':'social')&&x.originalId===(p.legacy?p.legacyId:p.id)).slice(0,12);
 return `<div class="detail-top"><button class="btn soft" data-action="navigate" data-id="feed">← Voltar ao Feed</button><span class="section-eyebrow">LEITURA / PUBLICAÇÃO</span></div>
 <div class="detail-hero"><span class="section-eyebrow">UNISYNC · BLOG</span><h1>${esc(p.title)}</h1><p>Uma publicação da comunidade universitária.</p></div>
 <div class="detail-stats"><span>♡ ${totalLikes} curtidas</span><span>💬 ${totalComments} comentários</span><span>↗ ${totalShares} compartilhamentos</span></div>
 ${postCard(p)}
 ${shares.length?`<div class="panel panel-pad detail-shares"><h3>Quem compartilhou (${shares.length})</h3><div class="share-people">${shares.map(sh=>{const u=profile(sh.authorId);return `<button data-action="view-profile" data-id="${attr(u.id)}">${avatar(u,'tiny')}<span>${esc(u.name)}</span></button>`;}).join('')}</div></div>`:''}`;
}

function postControls(p){
 const dev=isModerator(),own=p.authorId===state.me,status=postStatus(p);
 if(!dev&&!own)return '';
 const kind=p.legacy?'legacy':'social',id=p.legacy?p.legacyId:p.id;
 return `<div class="moderation-actions">
 ${status!=='aprovado'?`<span class="pill review-pill">${status==='pendente'?'Aguardando aprovação':'Não aprovado'}</span>`:''}
 ${dev&&status!=='aprovado'?`<button class="btn sm" data-action="moderate" data-id="${attr(kind+'|'+id+'|aprovado')}">✓ Aprovar</button>`:''}
 ${dev&&status==='pendente'?`<button class="btn sm line" data-action="moderate" data-id="${attr(kind+'|'+id+'|recusado')}">Recusar</button>`:''}
 ${own&&p.legacy&&status==='pendente'?`<button class="btn sm soft" data-action="mural-edit" data-id="${attr(id)}">Editar</button>`:''}
 <button class="btn sm danger" data-action="delete-post" data-id="${attr(kind+'|'+id)}">Excluir</button></div>`;
}
function feed(){
 const originals=[...state.posts,...unifiedLegacyPosts()];
 const reposts=state.shares.map(sh=>{const src=getOriginal(sh.sourceType==='legacy'?'legacy_'+sh.originalId:sh.originalId);return src&&postStatus(src)==='aprovado'?{id:'repost_'+sh.id,isRepost:true,original:src,authorId:sh.authorId,note:sh.note||'',title:src.title,body:src.body,tags:src.tags||[],createdAt:sh.createdAt,status:'aprovado'}:null;}).filter(Boolean);
 const all=[...originals,...reposts].filter(p=>postStatus(p)==='aprovado'||p.authorId===state.me||isModerator()).filter(p=>visible(p,p.title,p.body,(p.tags||[]).join(' '),p.legacyAuthorName||profile(p.authorId).name)).sort(byRecent);
 const pending=all.filter(p=>postStatus(p)==='pendente').length,filtered=state.feedFilter==='Pendentes'?all.filter(p=>postStatus(p)==='pendente'):all;
 return `<div class="global-strip"><div><b>💬 UFABC · Chat global</b><small>Aberto para todos que entram no UniSync.</small></div><button class="btn sm" data-action="open-global">Entrar no chat →</button></div>
 <div class="hero"><div class="section-eyebrow" style="color:#d5caff">BEM-VINDO À COMUNIDADE</div><h1>Histórias, ideias e conexões em um só lugar.</h1><p>Escreva, descubra e faça parte de algo. Todas as publicações ficam reunidas aqui.</p><div class="hero-actions"><button class="btn white" data-action="new-post">✎ Escrever um post</button><button class="btn" style="background:#ffffff27" data-action="navigate" data-id="rooms">Explorar grupos</button></div></div>
 <div class="panel composer"><div class="row">${avatar(me())}<button class="composer-trigger" data-action="new-post">Em que você está pensando hoje?</button></div><div class="composer-footer"><small>✦ Compartilhe histórias, dúvidas e descobertas</small><button class="btn sm" data-action="new-post">Publicar +</button></div></div>
 <div class="feed-head"><div><h2>Publicações</h2><small>Feed social e mural, em um só lugar</small></div><div class="feed-head-actions">${isModerator()?`<button class="btn sm soft" data-action="feed-filter" data-id="${state.feedFilter==='Todas'?'Pendentes':'Todas'}">${state.feedFilter==='Todas'?'Pendentes ('+pending+')':'Ver todas'}</button>`:''}<small>${filtered.length} posts</small></div></div>
 ${filtered.length?filtered.map(postCard).join(''):`<div class="panel empty">Nenhuma publicação nesta seleção.</div>`}`;
}
function postCard(p){if(p.isRepost)return repostCard(p);
 const old=p.legacy,author=old?{id:p.authorId,name:p.legacyAuthorName||'Estudante',university:p.legacyUni||'Universidade',avatarUrl:''}:profile(p.authorId);
 const myLike=state.likes.some(l=>l.postId===p.id&&l.userId===state.me),likes=state.likes.filter(l=>l.postId===p.id).length;
 const comments=state.comments.filter(c=>c.postId===p.id).sort(byRecent),expanded=state.commentOpen[p.id]||state.page==='post',cover=safeImg(p.coverUrl),approved=postStatus(p)==='aprovado';
 return `<article class="panel feed-post" id="post-${attr(p.id)}"><div class="row">${avatar(author)}<div class="grow">${old?`<strong>${esc(author.name)}</strong>`:`<button class="linkish" data-action="view-profile" data-id="${attr(author.id)}">${esc(author.name)}</button>`}<div class="subline">${esc(author.university)} · ${formatDate(p.createdAt)}</div></div><span class="pill">${old?'Mural':'Feed'}</span></div>
 <h3><button class="post-title-link" data-action="open-post" data-id="${attr(p.id)}">${esc(p.title)}</button></h3><p class="post-body">${esc(p.body)}</p>${cover?`<img class="post-cover" src="${attr(cover)}" alt="Imagem da publicação" loading="lazy">`:''}<div>${postTags(p.tags)}</div><div class="post-open-row"><button class="post-open-btn" data-action="open-post" data-id="${attr(p.id)}">Ler publicação completa ↗</button><span>↗ ${repostCount(p)} compartilhamentos</span></div>
 ${old?`<div class="post-actions"><span class="hint">Publicação do mural original</span><button class="action" data-action="share-post" data-id="${attr(p.id)}">Compartilhar</button></div>`:!approved?'<p class="hint">Interações disponíveis após aprovação.</p>':`<div class="post-actions"><button class="action ${myLike?'active':''}" data-action="like" data-id="${attr(p.id)}">${myLike?'💜':'♡'} ${likes} Curtidas</button><button class="action" data-action="comments" data-id="${attr(p.id)}">💬 ${comments.length} Comentários</button><button class="action" data-action="share-post" data-id="${attr(p.id)}">Compartilhar</button></div>`}
 ${postControls(p)}
 ${!old&&approved&&expanded?`<div class="comments">${comments.length?comments.map(c=>{const u=profile(c.authorId);return `<div class="comment">${avatar(u,'tiny')}<div class="bubble"><button class="linkish" data-action="view-profile" data-id="${attr(u.id)}">${esc(u.name)}</button> · <small>${formatDate(c.createdAt)}</small><div>${esc(c.text)}</div><button class="comment-like ${state.commentLikes.some(l=>l.commentId===c.id&&l.userId===state.me)?'active':''}" data-action="like-comment" data-id="${attr(c.id)}">Curtir: ${state.commentLikes.filter(l=>l.commentId===c.id).length}</button></div></div>`;}).join(''):'<p class="hint">Seja a primeira pessoa a comentar.</p>'}<form class="comment" data-form="comment" data-id="${attr(p.id)}">${avatar(me(),'tiny')}<input class="field" name="text" maxlength="500" required placeholder="Escreva um comentário..."><button class="btn sm" type="submit">Enviar</button></form></div>`:''}</article>`;
}
function notifications(){
 const items=activityEvents(),verb={like:'curtiu sua publicação',comment:'comentou sua publicação',share:'compartilhou sua publicação',follow:'começou a seguir você','comment-like':'curtiu seu comentário'};
 return `<div class="row between" style="margin-bottom:15px"><div><div class="section-eyebrow">Atualizações da sua comunidade</div><h1>Notificações</h1></div><span class="pill">🔔 ${items.length}</span></div>
 <p class="hint">Acompanhe curtidas, comentários, compartilhamentos, novos seguidores e curtidas em seus comentários. As novidades aparecem aqui enquanto você usa o aplicativo.</p>
 ${items.length?`<div class="panel notice-list">${items.map(e=>{const actor=profile(e.actorId);return `<button class="notice-item" data-action="${e.type==='follow'?'notification-profile':'notification-open'}" data-id="${attr(e.type==='follow'?e.actorId:e.postId)}">${avatar(actor,'sm')}<span class="grow"><strong>${esc(actor.name)}</strong> ${verb[e.type]||'interagiu com você'}${e.postTitle?`: <strong>“${esc(e.postTitle)}”</strong>`:''}${e.detail?`<small>${esc(e.detail.slice(0,105))}</small>`:''}</span><small>${e.createdAt?formatDate(e.createdAt):'Anterior'}</small></button>`;}).join('')}</div>`:`<div class="panel empty"><div class="empty-icon">🔔</div>Você ainda não recebeu interações. Quando alguém curtir, comentar, compartilhar ou seguir seu perfil, aparecerá aqui.</div>`}`;
}
function rooms(){const mine=state.rooms.filter(r=>member(r)&&r.kind!=='direct'&&visible(r,r.name,r.description));const discover=state.rooms.filter(r=>r.visibility==='public'&&!member(r)&&visible(r,r.name,r.description));return `<div class="row between" style="margin-bottom:18px"><div><div class="section-eyebrow">Encontre seu grupo</div><h1 style="margin:0">Comunidades</h1></div><button class="btn" data-action="new-room">+ Criar grupo</button></div><section style="margin-bottom:26px"><h3>Seus grupos <small>(${mine.length})</small></h3><div class="list">${mine.length?mine.map(roomCard).join(''):`<div class="panel empty">Você ainda não participa de nenhum grupo.</div>`}</div></section><section><h3>Comunidades abertas <small>(${discover.length})</small></h3><div class="list">${discover.length?discover.map(roomCard).join(''):`<div class="panel empty">Nenhuma comunidade pública para descobrir agora.</div>`}</div></section>`;}
function roomCard(r){const joined=member(r);return `<article class="panel room-card"><div class="avatar">${r.visibility==='private'?'🔒':'✦'}</div><div class="grow"><div class="row" style="gap:5px;flex-wrap:wrap"><strong>${esc(roomName(r))}</strong><span class="room-badge ${r.visibility==='private'?'private':''}">${r.visibility==='private'?'Privado':'Público'}</span></div><p>${esc(r.description||'Grupo para conhecer e conversar com estudantes.')}</p><small>${r.members?.length||0} participantes</small></div><button class="btn sm ${joined?'soft':''}" data-action="${joined?'open-room':'join-room'}" data-id="${attr(r.id)}">${joined?'Abrir':'Participar'}</button></article>`;}
function people(){const users=state.profiles.filter(p=>p.id!==state.me&&visible(p,p.name,p.username,p.university,p.bio,(p.tags||[]).map(t=>t.name).join(' ')));return `<div class="section-eyebrow">Comunidade UniSync</div><h1>Conheça pessoas</h1><p class="hint">Encontre estudantes, visite perfis públicos e comece uma conversa individual.</p><div class="list">${users.length?users.map(p=>`<article class="panel person-card">${avatar(p)}<div class="grow"><button class="linkish" data-action="view-profile" data-id="${attr(p.id)}">${esc(p.name)}</button><div class="subline">@${esc(p.username||'estudante')} · ${esc(p.university||'Universidade')}</div><div>${tags(p.tags)}</div></div><button class="btn sm soft" data-action="start-dm" data-id="${attr(p.id)}">💬 Conversar</button></article>`).join(''):`<div class="panel empty">Não encontramos estudantes nessa busca.</div>`}</div>`;}
function userProfile(){
 const p=profile(state.viewUserId||state.me),own=p.id===state.me,posts=state.posts.filter(x=>x.authorId===p.id&&(x.status==='aprovado'||own||isModerator())).sort(byRecent),cover=safeImg(p.bannerUrl);
 const followers=state.follows.filter(f=>f.followingId===p.id),following=state.follows.filter(f=>f.followerId===p.id);
 const isFollowing=state.follows.some(f=>f.followerId===state.me&&f.followingId===p.id);
 return `<div class="panel"><div class="profile-cover">${cover?`<img src="${attr(cover)}" alt="Banner do perfil">`:''}</div><div class="profile-content">
 <div class="profile-heading">${avatar(p,'big')}<div class="profile-buttons">
 ${own?`<button class="btn soft" data-action="edit-profile">✎ Editar perfil</button>`:`<button class="btn ${isFollowing?'soft':''}" data-action="toggle-follow" data-id="${attr(p.id)}">${isFollowing?'✓ Seguindo':'+ Seguir'}</button><button class="btn soft" data-action="start-dm" data-id="${attr(p.id)}">💬 Mensagem</button>`}</div></div>
 <h1 class="profile-title">${esc(p.name)}</h1><small>@${esc(p.username||'estudante')} · ${esc(p.university||'Universidade')}</small>
 <p class="bio">${esc(p.bio||'Este estudante ainda não adicionou uma biografia.')}</p><div class="profile-tags">${tags(p.tags)}${own?`<button class="btn sm soft" data-action="edit-profile">+ Tags</button>`:''}</div>
 <div class="stat-row"><div><b>${posts.length}</b><small>Publicações</small></div><button class="stat-link" data-action="view-follows" data-id="followers|${attr(p.id)}"><b>${followers.length}</b><small>Seguidores</small></button><button class="stat-link" data-action="view-follows" data-id="following|${attr(p.id)}"><b>${following.length}</b><small>Seguindo</small></button></div></div></div>
 <div class="feed-head"><h2>Publicações de ${esc(p.name)}</h2></div>${posts.length?posts.map(postCard).join(''):`<div class="panel empty">Ainda não há publicações neste perfil.</div>`}`;
}

function readState(m,r){const readers=state.receipts.filter(x=>x.roomId===r.id&&x.userId!==state.me&&timeValue(x.lastReadAt)>=timeValue(m.createdAt)-500);return readers.length?(r.kind==='direct'?'✓✓ Lida':'✓✓ Visto por '+readers.length):'✓ Enviada';}
function chats(){
 const myRooms=state.rooms.filter(r=>member(r)||r.id==='ufabc-global').filter(r=>visible(r,roomName(r),r.description)).sort((a,b)=>a.id==='ufabc-global'?-1:b.id==='ufabc-global'?1:byRecent(a,b));
 const r=state.rooms.find(x=>x.id===state.activeRoom&&(member(x)||x.id==='ufabc-global'))||null;
 const joined=r&&member(r);
 const roomMessages=joined?state.messages.filter(m=>m.roomId===r.id).sort((a,b)=>timeValue(a.createdAt)-timeValue(b.createdAt)):[];
 return `<div class="row between" style="margin-bottom:16px"><div><div class="section-eyebrow">Mensagens</div><h1 style="margin:0">Suas conversas</h1></div><button class="btn" data-action="new-room">+ Novo grupo</button></div>
 <div class="panel chat-layout ${r?'show-chat':''}">
 <div class="chat-side"><div class="chat-head">Conversas <small>(${myRooms.length})</small></div>
 ${myRooms.length?myRooms.map(x=>{const msgs=state.messages.filter(m=>m.roomId===x.id).sort(byRecent);return `<button class="chat-room ${state.activeRoom===x.id?'selected':''}" data-action="open-room" data-id="${attr(x.id)}"><div class="avatar">${x.kind==='direct'?'💬':x.visibility==='private'?'🔒':'✦'}</div><div class="grow"><div class="name">${esc(roomName(x))}</div><div class="subline">${!member(x)&&x.id==='ufabc-global'?'+ Entrar no chat':msgs[0]?esc(msgs[0].text.slice(0,30)):x.kind==='direct'?'Conversa privada':(x.members?.length||0)+' participantes'}</div></div></button>`;}).join(''):`<div class="empty">Nenhuma conversa. Explore as comunidades e participe de um grupo.</div>`}</div>
 <div class="chat-panel">${r?`<div class="chat-panel-head"><button class="btn sm line back-chat" data-action="chat-back" aria-label="Voltar à lista">←</button><div class="avatar sm">${r.kind==='direct'?'💬':'✦'}</div><div class="grow"><div class="name">${esc(roomName(r))}</div><div class="subline">${r.kind==='direct'?'Conversa individual':(r.members?.length||0)+' participantes · '+(r.visibility==='private'?'privado':'público')}</div></div>${joined&&r.kind!=='direct'&&r.ownerId===state.me?`<button class="btn sm soft" data-action="invite" data-id="${attr(r.id)}">+ Convidar</button>`:''}</div>
 ${!joined?`<div class="chat-join"><div class="empty-icon">💬</div><h3>Entre no chat ${esc(r.name||'UFABC')}</h3><p>Grupo público com ${r.members?.length||0} participantes. É necessário entrar antes de enviar mensagens.</p><button class="btn" data-action="join-room" data-id="${attr(r.id)}">+ Entrar no chat</button></div>`:`<div class="chat-messages" id="chat-messages">${roomMessages.length?roomMessages.map(m=>`<div class="message ${m.authorId===state.me?'mine':''}"><small>${esc(m.authorId===state.me?'Você':profile(m.authorId).name)} · ${formatTime(m.createdAt)}</small><div class="message-bubble">${esc(m.text)}</div>${m.authorId===state.me?`<small class="read-receipt">${readState(m,r)}</small>`:''}</div>`).join(''):`<div class="empty"><div class="empty-icon">💬</div>Comece a conversa com uma mensagem!</div>`}</div><form class="chat-footer msg-form" data-form="message" data-id="${attr(r.id)}"><input class="field" name="text" maxlength="1000" required autocomplete="off" placeholder="Escreva sua mensagem..." aria-label="Mensagem"><button class="btn" type="submit" aria-label="Enviar mensagem">➤</button></form>`}`:`<div class="empty" style="margin:auto"><div class="empty-icon">✦</div>Selecione uma conversa para começar.</div>`}</div></div>
 <p class="hint">${state.mode==='demo'?'Nesta demonstração, as mensagens ficam apenas neste navegador.':'As mensagens são sincronizadas pelo Firebase do UniSync.'} Grupos privados só aparecem para participantes.</p>`;
}
const SAUDE = {
  "Vacinação":[{t:"Mantenha a caderneta em dia",x:"Confira quais vacinas estão pendentes e procure uma UBS para atualizar. Leve um documento com foto e a caderneta de vacinação, se tiver."},{t:"Campanha de vacinação do semestre",x:"Aqui vão as datas e os locais das campanhas na universidade e na região.",ex:1}],
  "UBSs":[{t:"Encontre a UBS mais próxima",x:"As Unidades Básicas de Saúde atendem gratuitamente pelo SUS. Leve documento com foto e, se tiver, o Cartão SUS.",link:"https://www.google.com/maps/search/UBS+perto+de+mim"}],
  "Rodas de conversa":[{t:"Roda de conversa: ansiedade e rotina acadêmica",x:"Encontro aberto aos estudantes, promovido pela universidade. Data e local a definir.",ex:1},{t:"Roda de conversa: primeiros passos na vida adulta",x:"Troca de experiências sobre moradia, dinheiro e organização do tempo.",ex:1}],
  "Apoio emocional":[{t:"CVV – 188",x:"Apoio emocional gratuito, 24 horas por dia, por telefone.",tel:"188"},{t:"SAMU – 192",x:"Para emergências de saúde, ligue na hora.",tel:"192"},{t:"USP – Escritório de Saúde Mental",uni:"USP",x:"Ligado à Reitoria, oferece acolhimento psicológico voltado a orientação e prevenção. O atendimento é na Superintendência de Assistência Social (SAS), na Cidade Universitária.",link:"https://sites.usp.br/esm/formulario-do-esm/",lk:"Formulário do ESM"},
    {t:"Unicamp – SAPPE",uni:"Unicamp",x:"Serviço de Assistência Psicológica e Psiquiátrica ao Estudante, para alunos de graduação e pós-graduação. Contato: sappeass@unicamp.br ou (19) 3521-6643.",link:"mailto:sappeass@unicamp.br",lk:"Enviar e-mail",tel:"1935216643",tl:"(19) 3521-6643"},
    {t:"Unesp – NTAPS",uni:"Unesp",x:"O Núcleo Técnico de Atenção Psicossocial oferece acolhimento psicossocial a estudantes de graduação e pós-graduação de todas as unidades. Procure também a Seção Técnica de Saúde do seu câmpus."},
    {t:"UFABC – Seção Psicossocial (ProAP)",uni:"UFABC",x:"A Pró-Reitoria de Assuntos Comunitários e Políticas Afirmativas tem uma seção psicossocial para a comunidade. Veja formas de contato e horários no site da ProAP.",link:"https://proap.ufabc.edu.br",lk:"Site da ProAP"},
    {t:"Outras instituições",x:"Unifesp, UFSCar, IFSP, Univesp e Fatec: procure o setor de assuntos estudantis da sua instituição para saber do acolhimento psicológico."},
    {t:"Confira sempre o site oficial",x:"Serviços, horários e contatos mudam. Antes de contar com um deles, confirme no site da sua universidade."}]
};

const FIN_CATS=['Alimentação','Transporte','Moradia','Lazer','Estudos','Outros'];
const MURAL_CATS=['Festa','Trabalho autônomo','Processo seletivo','Outros'];
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function legacyList(){return [...new Map([...state.legacyPosts,...state.legacyMine,...state.legacyReview].map(p=>[p.id,p])).values()];}
function mural(){
  const data=legacyList().filter(p=>state.muralFilter==='Todas'||p.cat===state.muralFilter).sort((a,b)=>(timeValue(b.data)||0)-(timeValue(a.data)||0));
  const pending=legacyList().filter(p=>p.status==='pendente').length;
  return `<div class="row between"><div><div class="section-eyebrow">Mural original preservado</div><h1>Mural de avisos</h1></div><button class="btn" data-action="mural-new">+ Postagem</button></div>
  <p class="hint">Os avisos da primeira versão continuam aqui. Publicações novas passam por aprovação.</p>
  ${state.legacyRole==='moderador'?`<div class="notice">Você é moderador · ${pending} postagens pendentes</div>`:''}
  <div class="filters">${['Todas',...MURAL_CATS].map(c=>`<button class="pill ${c===state.muralFilter?'selected-pill':''}" data-action="mural-filter" data-id="${attr(c)}">${esc(c)}</button>`).join('')}</div>
  ${data.length?data.map(p=>{
    const own=p.autorUid===state.me;
    if(p.status!=='aprovado'&&!own&&state.legacyRole!=='moderador')return '';
    return `<article class="panel panel-pad legacy-post"><span class="pill">${esc(p.cat||'Outros')}</span>${p.status!=='aprovado'?`<span class="pill">${p.status==='pendente'?'Aguardando aprovação':'Recusada'}</span>`:''}
    <h3>${esc(p.titulo||'Publicação')}</h3><p class="post-body">${esc(p.texto||'')}</p><small class="subline">${esc(p.autorNome||'Aluno(a)')} · ${esc(p.autorUni||'Universidade')} · ${formatDate(p.data)}</small>
    <div class="legacy-actions">${own?`<button class="btn sm soft" data-action="mural-edit" data-id="${attr(p.id)}">Editar</button>`:''}
    ${(own||state.legacyRole==='moderador')?`<button class="btn sm danger" data-action="mural-delete" data-id="${attr(p.id)}">Apagar</button>`:''}
    ${state.legacyRole==='moderador'&&p.status==='pendente'?`<button class="btn sm" data-action="mural-status" data-id="${attr(p.id)}|aprovado">Aprovar</button><button class="btn sm line" data-action="mural-status" data-id="${attr(p.id)}|recusado">Recusar</button>`:''}</div></article>`;
  }).join(''):`<div class="panel empty">Nenhuma publicação nesta categoria.</div>`}`;
}
function finance(){
  const list=[...state.expenses].sort((a,b)=>(timeValue(b.data)||0)-(timeValue(a.data)||0));
  const total=list.reduce((sum,x)=>sum+Number(x.valor||0),0);
  const grouped=FIN_CATS.map(cat=>[cat,list.filter(x=>x.cat===cat).reduce((sum,x)=>sum+Number(x.valor||0),0)]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);
  return `<div class="row between"><div><div class="section-eyebrow">Seu controle pessoal</div><h1>Finanças</h1></div><button class="btn" data-action="new-expense">+ Novo gasto</button></div>
  <p class="hint">Seus gastos são privados e carregados do banco original do UniSync.</p>
  <div class="finance-total"><span>Total de gastos registrados</span><strong>${money(total)}</strong><small>${list.length} registros</small></div>
  <div class="panel panel-pad"><h3>Por categoria</h3>${grouped.length?grouped.map(([cat,value])=>`<div class="expense-cat"><div class="row between"><span>${esc(cat)}</span><strong>${money(value)}</strong></div><div class="expense-track"><div style="width:${total?Math.round(value/total*100):0}%"></div></div></div>`).join(''):'<p class="hint">Nenhum gasto registrado.</p>'}</div>
  <div class="panel panel-pad"><h3>Gastos recentes</h3>${list.length?list.map(x=>`<div class="expense-line"><div><strong>${esc(x.desc)}</strong><small>${esc(x.cat)} · ${formatDate(x.data)}</small></div><div><b>${money(x.valor)}</b><button class="btn sm line" data-action="expense-delete" data-id="${attr(x.id)}" aria-label="Apagar gasto">✕</button></div></div>`).join(''):'<p class="hint">Ainda não há lançamentos.</p>'}</div>`;
}
function health(){
  const choices=Object.keys(SAUDE),section=SAUDE[state.healthSection]||SAUDE['Vacinação'];
  return `<div class="section-eyebrow">Informação e acolhimento</div><h1>Saúde e bem-estar</h1><p class="hint">O conteúdo informativo da primeira versão continua disponível.</p><div class="filters">${choices.map(c=>`<button class="pill ${c===state.healthSection?'selected-pill':''}" data-action="health-tab" data-id="${attr(c)}">${esc(c)}</button>`).join('')}</div>
  ${section.map(c=>`<article class="panel panel-pad legacy-post"><h3>${esc(c.t)} ${c.ex?'<span class="pill">Exemplo</span>':''}</h3><p>${esc(c.x)}</p>${c.link?`<a class="btn sm" href="${attr(c.link)}" target="_blank" rel="noopener noreferrer">${esc(c.lk||'Abrir site')}</a>`:''}${c.tel?`<a class="btn sm soft" href="tel:${attr(c.tel)}">Ligar ${esc(c.tl||c.tel)}</a>`:''}</article>`).join('')}`;
}

function modal(){if(!state.modal)return '';const type=state.modal.type;let title='',body='',submit='Salvar';
if(type==='appearance')return `<div class="modal-backdrop" data-action="close-modal"><div class="modal small-modal" role="dialog" aria-modal="true" aria-label="Personalizar aparência"><div class="modal-head"><h2>Cores e aparência</h2><button class="close-btn" data-action="close-modal">×</button></div><div class="appearance-body"><p class="hint">Escolha o modo de exibição e uma cor de destaque. A escolha fica salva neste navegador.</p><h3>Modo de exibição</h3><div class="appearance-row"><button class="appearance-choice ${state.theme==='light'?'chosen':''}" data-action="set-theme" data-id="light">☀️ Claro</button><button class="appearance-choice ${state.theme==='dark'?'chosen':''}" data-action="set-theme" data-id="dark">🌙 Escuro</button></div><h3>Cor principal</h3><div class="accent-choices">${[['blue','#0B6FC2','Azul'],['purple','#7751D2','Roxo'],['green','#158E84','Verde'],['coral','#D66377','Coral']].map(([id,color,label])=>`<button class="accent-choice ${state.accent===id?'chosen':''}" data-action="set-accent" data-id="${id}"><i style="background:${color}"></i>${label}</button>`).join('')}</div><button class="btn" style="margin-top:15px;width:100%" data-action="close-modal">Concluído</button></div></div></div>`;
if(type==='share'){const original=getOriginal(state.modal.id);if(!original)return `<div class="modal-backdrop" data-action="close-modal"><div class="modal"><p>Esta publicação não está mais disponível.</p><button class="btn" data-action="close-modal">Fechar</button></div></div>`;const author=original.legacy?{name:original.legacyAuthorName||'Estudante',avatarUrl:''}:profile(original.authorId);return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="Compartilhar publicação"><div class="modal-head"><h2>Compartilhar no UniSync</h2><button class="close-btn" data-action="close-modal">×</button></div><form data-form="share"><p class="hint">Seu perfil publicará uma referência ao post original. O crédito e o link para o autor serão mantidos.</p><div class="share-inline">${avatar(author,'sm')}<div><strong>${esc(author.name)}</strong><p>${esc(original.title)}</p></div></div><label class="label">Escrever algo sobre esta publicação (opcional)</label><textarea class="field field-area" name="note" maxlength="600" placeholder="Por que você quer compartilhar isso?"></textarea><div class="modal-footer"><button type="button" class="btn line" data-action="close-modal">Cancelar</button><button class="btn" type="submit">Compartilhar no Feed</button></div></form></div></div>`;}

if(type==='follow-list'){
 const [kind,uid]=String(state.modal.id||'').split('|'),owner=profile(uid),list=state.follows.filter(f=>kind==='followers'?f.followingId===uid:f.followerId===uid).map(f=>profile(kind==='followers'?f.followerId:f.followingId));
 return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="Lista de seguidores"><div class="modal-head"><h2>${kind==='followers'?'Seguidores':'Seguindo'} de ${esc(owner.name)}</h2><button class="close-btn" data-action="close-modal">×</button></div><div class="follow-list">${list.length?list.map(u=>`<button class="follow-item" data-action="follow-profile" data-id="${attr(u.id)}">${avatar(u,'sm')}<span><b>${esc(u.name)}</b><small>@${esc(u.username||'estudante')}</small></span> →</button>`).join(''):'<p class="hint">Nenhum usuário nesta lista ainda.</p>'}</div></div></div>`;
}

if(type==='expense'){title='Novo gasto';submit='Registrar';body=`<label class="label">Descrição</label><input class="field" name="description" maxlength="60" required placeholder="Ex.: Lanche"><label class="label">Valor (R$)</label><input class="field" name="amount" type="number" min=".01" max="100000" step=".01" required><label class="label">Categoria</label><select class="field" name="category">${FIN_CATS.map(c=>`<option>${esc(c)}</option>`).join('')}</select>`;}
if(type==='legacy-post'){const old=legacyList().find(x=>x.id===state.modal.id);title=old?'Editar no mural':'Publicar no mural';submit='Enviar para aprovação';body=`<p class="hint">Publicações passam pela moderação antes de aparecerem para todos.</p><label class="label">Título</label><input class="field" name="title" maxlength="60" required value="${attr(old?.titulo||'')}"><label class="label">Categoria</label><select class="field" name="category">${MURAL_CATS.map(c=>`<option ${c===old?.cat?'selected':''}>${esc(c)}</option>`).join('')}</select><label class="label">Texto</label><textarea class="field field-area" name="body" maxlength="300" required>${esc(old?.texto||'')}</textarea>`;}
if(type==='post'){title='Criar publicação';submit='Enviar para aprovação';body=`<label class="label">Título do post</label><input class="field" name="title" maxlength="120" required placeholder="Dê um título à sua história"><label class="label">Seu texto</label><textarea class="field field-area" name="body" maxlength="5000" required placeholder="Compartilhe uma descoberta, dúvida, experiência ou ideia..."></textarea><label class="label">Assuntos (separe por vírgulas)</label><input class="field" name="tags" maxlength="130" placeholder="Ex.: Estudos, Tecnologia, Campus"><label class="label">URL pública de imagem (opcional, gratuita)</label><input class="field" type="url" name="coverUrl" placeholder="https://site.com/imagem.jpg"><p class="file-hint">Por enquanto, use um link HTTPS de imagem que você tenha direito de usar; upload direto está desativado.</p>`;}
if(type==='room'){title='Criar grupo';submit='Criar grupo';body=`<label class="label">Nome da comunidade</label><input class="field" name="name" minlength="3" maxlength="60" required placeholder="Ex.: Clube de Leitura"><label class="label">Descrição</label><textarea class="field" name="description" maxlength="250" placeholder="Sobre o que vocês vão conversar?"></textarea><label class="label">Privacidade</label><select class="field" name="visibility"><option value="public">🌐 Público — outros estudantes podem entrar</option><option value="private">🔒 Privado — somente convidados</option></select><label class="label">Convidar participantes (opcional, sem quantidade fixa)</label><div class="selection">${state.profiles.filter(x=>x.id!==state.me).map(p=>`<label><input type="checkbox" name="members" value="${attr(p.id)}">${avatar(p,'tiny')} ${esc(p.name)}</label>`).join('')}</div><p class="file-hint">Você pode convidar mais estudantes depois de criar o grupo.</p>`;}
if(type==='edit'){title='Personalizar perfil';submit='Salvar perfil';const p=me();body=`<label class="label">Nome de exibição</label><input class="field" name="name" maxlength="45" required value="${attr(p.name)}"><label class="label">Nome de usuário</label><input class="field" name="username" maxlength="25" required pattern="[a-zA-Z0-9._-]{3,25}" value="${attr(p.username||'estudante')}" placeholder="seu.usuario"><label class="label">Universidade</label><input class="field" name="university" maxlength="60" value="${attr(p.university||'')}"><label class="label">Biografia (até 500 caracteres)</label><textarea class="field field-area" name="bio" maxlength="500">${esc(p.bio||'')}</textarea><label class="label">Foto de perfil por URL (HTTPS)</label><input class="field" name="avatarUrl" type="url" value="${attr(p.avatarUrl||'')}" placeholder="https://site.com/perfil.jpg"><label class="label">Banner por URL (HTTPS)</label><input class="field" name="bannerUrl" type="url" value="${attr(p.bannerUrl||'')}" placeholder="https://site.com/banner.jpg"><p class="file-hint">Imagens por URL são gratuitas. Upload direto desativado, sem custo adicional.</p><label class="label">Tags coloridas</label><div id="tag-list">${tagEditor()}</div><div class="tag-edit-row"><input class="field" id="tag-label" maxlength="18" placeholder="Nome da tag (ex.: Gamer)"><input type="color" id="tag-color" value="#0B6FC2" aria-label="Cor da tag"><button type="button" class="btn sm soft" data-action="add-tag">Adicionar</button></div><p class="file-hint">Escolha nomes e cores para até 8 tags.</p>`;}
if(type==='invite'){const r=state.rooms.find(x=>x.id===state.modal.id);title='Convidar participantes';submit='Enviar convites';body=`<p class="hint">Adicione estudantes ao grupo ${esc(r?.name||'')}.</p><div class="selection">${state.profiles.filter(p=>p.id!==state.me&&!r?.members.includes(p.id)).map(p=>`<label><input type="checkbox" name="members" value="${attr(p.id)}">${avatar(p,'tiny')} ${esc(p.name)}</label>`).join('')||'<p class="hint">Todos os estudantes conhecidos já participam deste grupo.</p>'}</div>`;}
return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${attr(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="close-btn" data-action="close-modal" aria-label="Fechar">×</button></div><form data-form="${type}">${body}<div class="modal-footer"><button type="button" class="btn line" data-action="close-modal">Cancelar</button><button class="btn" type="submit">${submit}</button></div></form></div></div>`;}
function tagEditor(){return state.draftTags.map((t,i)=>`<div class="row between" style="margin:5px 0"><span class="pill tag" style="--tag-color:${cleanColor(t.color)}">${esc(t.name)}</span><button class="btn sm danger" data-action="remove-tag" data-id="${i}">Remover</button></div>`).join('')||'<p class="hint">Nenhuma tag adicionada ainda.</p>';}
function showModal(type,id){state.modal={type,id};if(type==='edit')state.draftTags=(me().tags||[]).map(t=>({...t}));render();}
function render(){if(!state.me){root.innerHTML=authView();return;}if(state.mode==='firebase'&&state.enterGate){root.innerHTML=entryView();return;}root.innerHTML=layout();const box=document.getElementById('chat-messages');if(box)box.scrollTop=box.scrollHeight;}
function entryView(){
 const user=me();
 return `<div class="auth-shell"><div class="panel auth-card entry-card">
 <button class="theme-btn auth-theme" data-action="open-appearance" aria-label="Configurar aparência">🎨</button>
 <div class="brand"><span class="legacy-logo" role="img" aria-label="Logotipo UniSync"></span></div>
 <h1>Entrar no UniSync</h1><p>Sua conta está conectada, mas o aplicativo só será aberto quando você escolher entrar.</p>
 <div class="entry-user">${avatar(user,'sm')}<div><strong>${esc(user.name)}</strong><small>${esc(user.university||'Universidade')}</small></div></div>
 <button class="btn entry-btn" data-action="enter-app">Entrar no meu Feed</button>
 <button class="btn soft entry-btn" data-action="switch-account">Usar outra conta</button>
 <p class="hint">Para sair a qualquer momento, use o botão Sair no topo do aplicativo.</p>
 </div></div>${modal()}`;
}
function authView(){return `<div class="auth-shell"><div class="panel auth-card"><button class="theme-btn auth-theme" data-action="open-appearance" title="Configurar aparência">🎨</button><div class="brand"><span class="legacy-logo" role="img" aria-label="Logotipo UniSync"></span></div><h1>${state.authMode==='register'?'Criar conta':'Bem-vindo de volta!'}</h1><p>Conecte-se à comunidade universitária.</p><form data-form="auth"><label class="label">E-mail</label><input class="field" type="email" name="email" autocomplete="email" required><label class="label">Senha</label><input class="field" type="password" name="password" minlength="6" autocomplete="${state.authMode==='register'?'new-password':'current-password'}" required><button class="btn" type="submit">${state.authMode==='register'?'Criar conta':'Entrar'}</button></form><button class="btn soft" data-action="google-auth">Continuar com Google</button><div style="text-align:center"><button class="linkish" data-action="toggle-auth">${state.authMode==='register'?'Já tenho uma conta':'Ainda não tenho conta'}</button> <button class="linkish" data-action="forgot-password">Esqueci minha senha</button></div><p class="hint">Após o cadastro, confirme seu e-mail antes de entrar. Você usa o Firebase do UniSync.</p></div></div>${modal()}`;}
root.addEventListener('input',e=>{if(e.target.id==='global-search'){state.search=e.target.value;const node=document.getElementById('content');if(node)node.innerHTML=content();}});
root.addEventListener('change',e=>{if(e.target.id==='demo-persona'){run(()=>api.chooseDemoUser(e.target.value));}});
root.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='close-modal'&&el!==e.target)return;const action=el.dataset.action,id=el.dataset.id;
  if(action==='navigate'){go(id);return;}
  if(action==='enter-app'){state.enterGate=false;state.page='feed';state.viewPostId=null;render();return;}
  if(action==='switch-account'){state.loginRequested=false;state.enterGate=true;await run(()=>api.logout());return;}
  if(action==='open-appearance'){showModal('appearance');return;}
  if(action==='set-theme'){state.theme=id==='dark'?'dark':'light';document.documentElement.dataset.theme=state.theme;try{localStorage.setItem('unisync_theme',state.theme);}catch{}render();return;}
  if(action==='set-accent'){if(!['blue','purple','green','coral'].includes(id))return;state.accent=id;document.documentElement.dataset.accent=id;try{localStorage.setItem('unisync_accent',id);}catch{}render();return;}
  if(action==='open-post'){state.viewPostId=id;state.commentOpen[id]=true;state.page='post';state.modal=null;state.search='';render();return;}

  if(action==='toggle-theme'){state.theme=state.theme==='light'?'dark':'light';document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.accent=state.accent;try{localStorage.setItem('unisync_theme',state.theme);}catch{}render();return;}
  if(action==='toggle-follow'){if(id===state.me)return;await run(()=>api.toggleFollow(id));return;}
  if(action==='view-follows'){showModal('follow-list',id);return;}
  if(action==='follow-profile'){state.modal=null;state.viewUserId=id;state.page='profile';render();return;}
  if(action==='like-comment'){await run(()=>api.toggleCommentLike(id));return;}
  if(action==='share-post'){const p=getOriginal(id);if(!p||postStatus(p)!=='aprovado'){alertToast('Somente publicações aprovadas podem ser compartilhadas.','error');return;}showModal('share',id);return;}

  if(action==='close-more'){state.mobileMore=false;render();return;}
  if(action==='feed-filter'){state.feedFilter=id;render();return;}
  if(action==='notification-open'){state.viewPostId=id;state.commentOpen[id]=true;state.page='post';state.search='';render();return;}
  if(action==='notification-profile'){state.viewUserId=id;state.page='profile';state.search='';render();return;}
  if(action==='moderate'){const [kind,pid,status]=id.split('|');await run(()=>kind==='legacy'?api.legacyStatus(pid,status):api.socialStatus(pid,status),'Publicação atualizada');return;}
  if(action==='delete-post'){const [kind,pid]=id.split('|');if(!confirm('Excluir esta publicação permanentemente?'))return;await run(()=>kind==='legacy'?api.legacyDelete(pid):api.socialDelete(pid),'Publicação excluída');return;}
  if(action==='open-global'){if(!state.rooms.some(r=>r.id==='ufabc-global')){alertToast('O grupo UFABC será disponibilizado ao entrar com uma conta institucional.','error');return;}openRoom('ufabc-global');return;}
  if(action==='logout'){state.enterGate=true;state.loginRequested=false;await run(()=>api.logout());return;}
  if(action==='forgot-password'){const email=document.querySelector('form[data-form="auth"] [name="email"]')?.value.trim();if(!email){alertToast('Digite seu e-mail institucional.','error');return;}await run(()=>api.resetPassword(email),'Confira seu e-mail para redefinir a senha.');return;}
  if(action==='mural-new'){showModal('legacy-post');return;}
  if(action==='mural-edit'){showModal('legacy-post',id);return;}
  if(action==='mural-delete'){if(confirm('Excluir esta publicação?'))await run(()=>api.legacyDelete(id));return;}
  if(action==='mural-status'){const [postId,status]=id.split('|');await run(()=>api.legacyStatus(postId,status));return;}
  if(action==='mural-filter'){state.muralFilter=id;render();return;}
  if(action==='health-tab'){state.healthSection=id;render();return;}
  if(action==='new-expense'){showModal('expense');return;}
  if(action==='expense-delete'){if(confirm('Apagar este gasto?'))await run(()=>api.deleteExpense(id));return;}
  if(action==='my-profile'){go('profile');return;}
  if(action==='view-profile'){state.viewUserId=id;state.page='profile';state.search='';render();return;}
  if(action==='new-post'){showModal('post');return;}
  if(action==='new-room'){showModal('room');return;}
  if(action==='edit-profile'){showModal('edit');return;}
  if(action==='invite'){showModal('invite',id);return;}
  if(action==='close-modal'){state.modal=null;render();return;}
  if(action==='like'){await run(()=>api.toggleLike(id));return;}
  if(action==='comments'){state.commentOpen[id]=!state.commentOpen[id];render();return;}
  if(action==='join-room'){await run(async()=>{await api.joinRoom(id);openRoom(id);},'Você entrou no grupo!');return;}
  if(action==='open-room'){openRoom(id);return;}
  if(action==='chat-back'){state.activeRoom=null;subscribeRoom(null);render();return;}
  if(action==='start-dm'){if(id===state.me)return;await run(async()=>openRoom(await api.startDirect(id)),'Conversa aberta');return;}
  if(action==='add-tag'){const name=document.getElementById('tag-label')?.value.trim(),color=cleanColor(document.getElementById('tag-color')?.value);if(!name)return;if(state.draftTags.length>=8)return alertToast('Limite de 8 tags.','error');if(state.draftTags.some(t=>t.name.toLowerCase()===name.toLowerCase()))return alertToast('Essa tag já foi adicionada.','error');state.draftTags.push({name:name.slice(0,18),color});document.getElementById('tag-list').innerHTML=tagEditor();document.getElementById('tag-label').value='';return;}
  if(action==='remove-tag'){state.draftTags.splice(Number(id),1);document.getElementById('tag-list').innerHTML=tagEditor();return;}
  if(action==='google-auth'){state.loginRequested=true;await run(()=>api.signInGoogle());return;}
  if(action==='toggle-auth'){state.authMode=state.authMode==='login'?'register':'login';render();return;}
  if(action==='reset-demo'){await run(()=>api.resetDemo(),'Demonstração reiniciada');return;}
});
function subscribeRoom(id){const target=id||null;if(state.watchingRoomId===target)return;state.watchingRoomId=target;api?.watchMessages(target);}
function openRoom(id){const r=state.rooms.find(x=>x.id===id);if(r&&!member(r)&&r.id!=='ufabc-global'){alertToast('Entre no grupo antes de conversar.','error');return;}state.activeRoom=id;state.page='chats';state.modal=null;state.search='';subscribeRoom(r&&member(r)?id:null);render();}
root.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const kind=form.dataset.form,fd=new FormData(form),str=name=>String(fd.get(name)||'').trim();const button=form.querySelector('[type=submit]');if(button)button.disabled=true;
  try{
    if(kind==='share'){const source=getOriginal(state.modal?.id),note=str('note').slice(0,600);if(!source||postStatus(source)!=='aprovado')throw Error('Esta publicação não está disponível para compartilhar.');await api.createShare({sourceType:source.legacy?'legacy':'social',originalId:source.legacy?source.legacyId:source.id,note});state.modal=null;state.page='feed';render();alertToast('Compartilhado no seu Feed!');return;}
    if(kind==='legacy-post'){const title=str('title'),body=str('body'),category=str('category');if(title.length<3||body.length<10)throw Error('Preencha o título e um texto com pelo menos 10 caracteres.');await api.legacyPost({title,body,category},state.modal?.id||null);state.modal=null;render();alertToast('Postagem enviada para moderação.');return;}
    if(kind==='expense'){const description=str('description'),amount=Number(str('amount').replace(',','.')),category=str('category');if(description.length<2||!Number.isFinite(amount)||amount<=0||amount>100000)throw Error('Informe descrição e valor válidos.');await api.addExpense({description,amount:Math.round(amount*100)/100,category});state.modal=null;render();alertToast('Gasto registrado!');return;}
    if(kind==='auth'){const email=str('email'),password=str('password');if(state.authMode==='register'){await api.register(email,password);alertToast('Conta criada! Confira seu e-mail para confirmar o cadastro.');state.authMode='login';}else{state.loginRequested=true;await api.login(email,password);}render();return;}
    if(kind==='post'){const title=str('title'),body=str('body'),topics=str('tags').split(',').map(x=>x.trim().slice(0,24)).filter(Boolean).slice(0,6);if(title.length<3||body.length<5)throw Error('Preencha um título e um texto mais completos.');const coverUrl=str('coverUrl');if(coverUrl&&!safeImg(coverUrl))throw Error('Use um link de imagem HTTPS válido.');await api.createPost({title,body,tags:topics,coverUrl});state.modal=null;render();alertToast('Post enviado para aprovação.');return;}
    if(kind==='room'){const name=str('name'),description=str('description'),visibility=str('visibility'),members=fd.getAll('members').map(String);if(name.length<3||!['public','private'].includes(visibility))throw Error('Preencha os dados do grupo.');const id=await api.createRoom({name,description,visibility,kind:'group',members});state.modal=null;openRoom(id);alertToast('Grupo criado com sucesso!');return;}
    if(kind==='edit'){const name=str('name'),username=str('username'),university=str('university'),bio=str('bio');if(!name||!/^[a-zA-Z0-9._-]{3,25}$/.test(username))throw Error('O nome de usuário deve ter de 3 a 25 caracteres, usando letras, números, pontos, hífens ou _.');const avatarUrl=str('avatarUrl'),bannerUrl=str('bannerUrl');if((avatarUrl&&!safeImg(avatarUrl))||(bannerUrl&&!safeImg(bannerUrl)))throw Error('As imagens precisam de links HTTPS.');const changes={name,username,university,bio,tags:state.draftTags,avatarUrl,bannerUrl};await api.saveProfile(changes);state.modal=null;render();alertToast('Perfil atualizado!');return;}
    if(kind==='invite'){const members=fd.getAll('members').map(String);for(const uid of members)await api.addMember(state.modal.id,uid);state.modal=null;render();alertToast('Participantes adicionados!');return;}
    if(kind==='comment'){const text=str('text');if(!text)return;await api.comment(form.dataset.id,text.slice(0,500));form.reset();return;}
    if(kind==='message'){const room=state.rooms.find(r=>r.id===form.dataset.id);if(!room||!member(room))throw Error('Entre no grupo antes de enviar mensagens.');const text=str('text');if(!text)return;await api.sendMessage(form.dataset.id,text.slice(0,1000));form.reset();return;}
  }catch(ex){console.error(ex);alertToast(ex.message||'Não foi possível salvar.','error');}finally{if(button)button.disabled=false;}
});
const onData=(kind,items)=>{if(kind in state)state[kind]=items;if(kind==='messages'&&state.me&&state.page==='chats'&&state.activeRoom&&state.rooms.some(r=>r.id===state.activeRoom&&member(r))){const newest=Math.max(0,...items.filter(m=>m.roomId===state.activeRoom&&m.authorId!==state.me).map(m=>timeValue(m.createdAt)));if(newest>0&&newest>(state.lastReadMarked[state.activeRoom]||0)){state.lastReadMarked[state.activeRoom]=newest;api?.markRoomRead?.(state.activeRoom).catch(e=>console.warn('Leitura:',e.message));}}if(kind==='posts'&&state.shareTarget&&items.some(p=>p.id===state.shareTarget)){const target=state.shareTarget;state.shareTarget=null;state.page='post';state.viewPostId=target;}if(kind==='rooms'&&state.me&&!state.globalAutoOpened&&items.some(x=>x.id==='ufabc-global')){state.globalAutoOpened=true;state.activeRoom='ufabc-global';}if(kind==='rooms'&&state.me&&state.page==='chats'&&state.activeRoom){const active=items.find(r=>r.id===state.activeRoom);subscribeRoom(active&&member(active)?active.id:null);}if(state.me)render();};
const onAuth=user=>{if(user?.id!==state.me){state.lastReadMarked={};state.watchingRoomId=null;try{state.notificationsSeen=Number(localStorage.getItem('unisync_notifications_seen_'+user?.id))||0;}catch{state.notificationsSeen=0;}}const isNewLogin=user?.id!==state.me;state.me=user?.id||null;state.mode=user?.mode||'firebase';if(state.me&&isNewLogin){state.page='feed';state.viewPostId=null;state.enterGate=state.mode==='firebase'&&!state.loginRequested;state.loginRequested=false;}if(!state.me){state.enterGate=true;state.loginRequested=false;}if(!state.me){state.globalAutoOpened=false;state.activeRoom=null;}else if(!state.globalAutoOpened&&state.rooms.some(r=>r.id==='ufabc-global')){state.globalAutoOpened=true;state.activeRoom='ufabc-global';}if(state.me&&!state.profiles.some(p=>p.id===state.me)&&state.mode==='firebase'){state.page='feed';}render();};
try{api=await createAdapter(onData,onAuth,msg=>alertToast(msg,'error'));state.mode=api.mode;if(state.mode==='firebase'&&!state.me)render();}catch(error){console.error(error);root.innerHTML=`<div class="auth-shell"><div class="panel panel-pad"><h2>Não foi possível iniciar o UniSync</h2><p>${esc(error.message)}</p><p class="hint">Confira o Firebase de testes ou abra a versão de demonstração com a configuração nula.</p></div></div>`;}
